package react

type reactor struct {
	computes []*cell
}

type cell struct {
	r       *reactor
	value   int
	compute func() int
	cbs     map[int]func(int)
	nextID  int
}

type canceler struct {
	c  *cell
	id int
}

func (c *canceler) Cancel() {
	delete(c.c.cbs, c.id)
}

func (c *cell) Value() int {
	return c.value
}

func (c *cell) SetValue(value int) {
	if c.value == value {
		return
	}
	c.value = value
	old := make([]int, len(c.r.computes))
	for i, cc := range c.r.computes {
		old[i] = cc.value
		cc.value = cc.compute()
	}
	for i, cc := range c.r.computes {
		if cc.value != old[i] {
			for _, cb := range cc.cbs {
				cb(cc.value)
			}
		}
	}
}

func (c *cell) AddCallback(callback func(int)) Canceler {
	id := c.nextID
	c.nextID++
	c.cbs[id] = callback
	return &canceler{c, id}
}

func New() Reactor {
	return &reactor{}
}

func (r *reactor) CreateInput(initial int) InputCell {
	return &cell{r: r, value: initial, cbs: map[int]func(int){}}
}

func (r *reactor) add(f func() int) *cell {
	c := &cell{r: r, compute: f, cbs: map[int]func(int){}}
	c.value = f()
	r.computes = append(r.computes, c)
	return c
}

func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	return r.add(func() int { return compute(dep.Value()) })
}

func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	return r.add(func() int { return compute(dep1.Value(), dep2.Value()) })
}

