const ANIMALS = [
  { name: 'fly', line: '' },
  { name: 'spider', line: 'It wriggled and jiggled and tickled inside her.\n', extra: ' that wriggled and jiggled and tickled inside her' },
  { name: 'bird', line: 'How absurd to swallow a bird!\n' },
  { name: 'cat', line: 'Imagine that, to swallow a cat!\n' },
  { name: 'dog', line: 'What a hog, to swallow a dog!\n' },
  { name: 'goat', line: 'Just opened her throat and swallowed a goat!\n' },
  { name: 'cow', line: "I don't know how she swallowed a cow!\n" },
  { name: 'horse', line: "She's dead, of course!\n" },
];

export class Song {
  verse(n) {
    const a = ANIMALS[n - 1];
    let out = `I know an old lady who swallowed a ${a.name}.\n` + a.line;
    if (n === 8) return out;
    for (let i = n - 1; i > 0; i--) {
      const prey = ANIMALS[i - 1];
      out += `She swallowed the ${ANIMALS[i].name} to catch the ${prey.name}${prey.extra || ''}.\n`;
    }
    out += "I don't know why she swallowed the fly. Perhaps she'll die.\n";
    return out;
  }

  verses(start, end) {
    let out = '';
    for (let i = start; i <= end; i++) out += this.verse(i) + '\n';
    return out;
  }
}

