class StackUnderflowError(Exception):
    """Raised when the stack has too few items."""
    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_num(tok):
    return tok.lstrip('-').isdigit() and tok not in ('-',)


def _need(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")


def evaluate(input_data):
    defs = {}
    stack = []
    builtins = {'+', '-', '*', '/', 'dup', 'drop', 'swap', 'over'}

    def expand(tok):
        if tok in defs:
            return defs[tok]
        return [tok]

    for line in input_data:
        tokens = line.lower().split()
        if tokens and tokens[0] == ':':
            if len(tokens) < 3 or tokens[-1] != ';':
                raise ValueError("undefined operation")
            name = tokens[1]
            if _is_num(name):
                raise ValueError("illegal operation")
            body = []
            for t in tokens[2:-1]:
                body.extend(expand(t))
            defs[name] = body
            continue
        program = []
        for t in tokens:
            program.extend(expand(t))
        for t in program:
            if _is_num(t):
                stack.append(int(t))
            elif t in builtins:
                if t in ('+', '-', '*', '/'):
                    _need(stack, 2)
                    b = stack.pop()
                    a = stack.pop()
                    if t == '+':
                        stack.append(a + b)
                    elif t == '-':
                        stack.append(a - b)
                    elif t == '*':
                        stack.append(a * b)
                    else:
                        if b == 0:
                            raise ZeroDivisionError("divide by zero")
                        q = abs(a) // abs(b)
                        stack.append(q if (a >= 0) == (b >= 0) else -q)
                elif t == 'dup':
                    _need(stack, 1)
                    stack.append(stack[-1])
                elif t == 'drop':
                    _need(stack, 1)
                    stack.pop()
                elif t == 'swap':
                    _need(stack, 2)
                    stack[-1], stack[-2] = stack[-2], stack[-1]
                elif t == 'over':
                    _need(stack, 2)
                    stack.append(stack[-2])
            else:
                raise ValueError("undefined operation")
    return stack

