package react

// Define reactor, cell and canceler types here.
// These types will implement the Reactor, Cell and Canceler interfaces, respectively.

type reactor struct {
	cells []*cell // all cells in creation order (a valid topological order)
}

type cell struct {
	reactor   *reactor
	value     int
	isInput   bool
	eval      func() int
	callbacks []*callbackEntry
	nextID    int
}

type callbackEntry struct {
	id       int
	callback func(int)
}

type canceler struct {
	cell *cell
	id   int
}

func (c *canceler) Cancel() {
	if c.cell == nil {
		return
	}
	cbs := c.cell.callbacks
	for i, e := range cbs {
		if e.id == c.id {
			c.cell.callbacks = append(cbs[:i:i], cbs[i+1:]...)
			break
		}
	}
}

func (c *cell) Value() int {
	return c.value
}

func (c *cell) SetValue(value int) {
	if !c.isInput {
		return
	}
	r := c.reactor

	// Snapshot values before the update.
	old := make([]int, len(r.cells))
	for i, cl := range r.cells {
		old[i] = cl.value
	}

	c.value = value

	// Recompute compute cells in topological (creation) order.
	for _, cl := range r.cells {
		if !cl.isInput {
			cl.value = cl.eval()
		}
	}

	// Notify callbacks for cells whose stable value changed.
	for i, cl := range r.cells {
		if cl.value == old[i] {
			continue
		}
		// Copy callbacks so cancellations during iteration are safe.
		entries := make([]*callbackEntry, len(cl.callbacks))
		copy(entries, cl.callbacks)
		for _, e := range entries {
			e.callback(cl.value)
		}
	}
}

func (c *cell) AddCallback(callback func(int)) Canceler {
	id := c.nextID
	c.nextID++
	c.callbacks = append(c.callbacks, &callbackEntry{id: id, callback: callback})
	return &canceler{cell: c, id: id}
}

func New() Reactor {
	return &reactor{}
}

func (r *reactor) CreateInput(initial int) InputCell {
	c := &cell{reactor: r, value: initial, isInput: true}
	r.cells = append(r.cells, c)
	return c
}

func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	d := dep.(*cell)
	c := &cell{reactor: r}
	c.eval = func() int { return compute(d.value) }
	c.value = c.eval()
	r.cells = append(r.cells, c)
	return c
}

func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	d1 := dep1.(*cell)
	d2 := dep2.(*cell)
	c := &cell{reactor: r}
	c.eval = func() int { return compute(d1.value, d2.value) }
	c.value = c.eval()
	r.cells = append(r.cells, c)
	return c
}

