//
// Food Chain exercise implementation.
//

const ANIMALS = [
  'fly',
  'spider',
  'bird',
  'cat',
  'dog',
  'goat',
  'cow',
  'horse',
];

const COMMENTS = {
  spider: 'It wriggled and jiggled and tickled inside her.',
  bird: 'How absurd to swallow a bird!',
  cat: 'Imagine that, to swallow a cat!',
  dog: 'What a hog, to swallow a dog!',
  goat: 'Just opened her throat and swallowed a goat!',
  cow: "I don't know how she swallowed a cow!",
  horse: "She's dead, of course!",
};

const FINAL_LINE = "I don't know why she swallowed the fly. Perhaps she'll die.";

export class Song {
  verse(n) {
    const index = n - 1;
    const animal = ANIMALS[index];
    const lines = [`I know an old lady who swallowed a ${animal}.`];

    if (animal === 'horse') {
      lines.push(COMMENTS.horse);
      return `${lines.join('\n')}\n`;
    }

    if (COMMENTS[animal]) {
      lines.push(COMMENTS[animal]);
    }

    for (let i = index; i >= 1; i -= 1) {
      let line = `She swallowed the ${ANIMALS[i]} to catch the ${ANIMALS[i - 1]}`;
      if (ANIMALS[i - 1] === 'spider') {
        line += ' that wriggled and jiggled and tickled inside her';
      }
      lines.push(`${line}.`);
    }

    if (index > 0) {
      lines.push(FINAL_LINE);
    } else {
      lines.push(FINAL_LINE);
    }

    return `${lines.join('\n')}\n`;
  }

  verses(start, end) {
    const parts = [];
    for (let n = start; n <= end; n += 1) {
      parts.push(`${this.verse(n)}\n`);
    }
    return parts.join('');
  }
}

