class StackUnderflowError(Exception):
    """Exception raised when the stack does not have enough items."""

    def __init__(self, message):
        super().__init__(message)
        self.message = message


UNDERFLOW_MSG = "Insufficient number of items in stack"


def _need(stack, n):
    if len(stack) < n:
        raise StackUnderflowError(UNDERFLOW_MSG)


def _binop(func):
    def op(stack):
        _need(stack, 2)
        b = stack.pop()
        a = stack.pop()
        stack.append(func(a, b))
    return op


def _add(a, b):
    return a + b


def _sub(a, b):
    return a - b


def _mul(a, b):
    return a * b


def _div(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    return a // b


def _dup(stack):
    _need(stack, 1)
    stack.append(stack[-1])


def _drop(stack):
    _need(stack, 1)
    stack.pop()


def _swap(stack):
    _need(stack, 2)
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _over(stack):
    _need(stack, 2)
    stack.append(stack[-2])


def _undefined(stack):
    raise ValueError("undefined operation")


BUILTINS = {
    "+": _binop(_add),
    "-": _binop(_sub),
    "*": _binop(_mul),
    "/": _binop(_div),
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _compile_token(token, defs):
    """Return a list of items (ints or stack functions) for a token."""
    if token.isdigit():
        return [int(token)]
    if token in defs:
        return defs[token]
    if token in BUILTINS:
        return [BUILTINS[token]]
    return [_undefined]


def _run(items, stack):
    for item in items:
        if isinstance(item, int):
            stack.append(item)
        else:
            item(stack)


def evaluate(input_data):
    stack = []
    defs = {}
    tokens = []
    for line in input_data:
        tokens.extend(line.split())

    i = 0
    while i < len(tokens):
        tok = tokens[i].lower()
        if tok == ":":
            if i + 1 >= len(tokens):
                raise ValueError("illegal operation")
            name = tokens[i + 1].lower()
            if name.isdigit() or name in (":", ";"):
                raise ValueError("illegal operation")
            end = None
            for k in range(i + 2, len(tokens)):
                if tokens[k] == ";":
                    end = k
                    break
            if end is None:
                raise ValueError("illegal operation")
            compiled = []
            for body_tok in tokens[i + 2:end]:
                compiled.extend(_compile_token(body_tok.lower(), defs))
            defs[name] = compiled
            i = end + 1
        else:
            _run(_compile_token(tok, defs), stack)
            i += 1

    return stack

