package react

// reactor keeps every cell in creation order, which is a valid topological
// order because a cell's dependencies must exist before the cell does.
type reactor struct {
	cells []*cell
}

// cell is used for both input cells (compute == nil) and compute cells.
type cell struct {
	reactor    *reactor
	value      int
	compute    func() int
	dependents []*cell
	callbacks  map[int]func(int)
	nextID     int
}

// canceler removes a single callback from a cell.
type canceler struct {
	c  *cell
	id int
}

func (c *canceler) Cancel() {
	if c == nil || c.c == nil || c.c.callbacks == nil {
		return
	}
	delete(c.c.callbacks, c.id)
}

func (c *cell) Value() int {
	return c.value
}

func (c *cell) SetValue(value int) {
	if c.compute != nil {
		// Only input cells are settable; ignore otherwise.
		return
	}
	if value == c.value {
		return
	}

	r := c.reactor
	before := make([]int, len(r.cells))
	for i, cl := range r.cells {
		before[i] = cl.value
	}

	c.value = value

	// Recompute compute cells in creation (topological) order.
	for _, cl := range r.cells {
		if cl.compute != nil {
			cl.value = cl.compute()
		}
	}

	// Collect changed cells, then fire callbacks after propagation completes.
	var changed []*cell
	for i, cl := range r.cells {
		if cl.compute != nil && cl.value != before[i] {
			changed = append(changed, cl)
		}
	}
	for _, cl := range changed {
		// Snapshot callbacks so cancellations during iteration are safe.
		cbs := make([]func(int), 0, len(cl.callbacks))
		for _, cb := range cl.callbacks {
			cbs = append(cbs, cb)
		}
		for _, cb := range cbs {
			cb(cl.value)
		}
	}
}

func (c *cell) AddCallback(callback func(int)) Canceler {
	if c.callbacks == nil {
		c.callbacks = make(map[int]func(int))
	}
	id := c.nextID
	c.nextID++
	c.callbacks[id] = callback
	return &canceler{c: c, id: id}
}

func New() Reactor {
	return &reactor{}
}

func (r *reactor) CreateInput(initial int) InputCell {
	c := &cell{reactor: r, value: initial}
	r.cells = append(r.cells, c)
	return c
}

func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	d1 := dep.(*cell)
	c := &cell{reactor: r}
	c.compute = func() int { return compute(d1.value) }
	d1.dependents = append(d1.dependents, c)
	c.value = c.compute()
	r.cells = append(r.cells, c)
	return c
}

func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	d1 := dep1.(*cell)
	d2 := dep2.(*cell)
	c := &cell{reactor: r}
	c.compute = func() int { return compute(d1.value, d2.value) }
	d1.dependents = append(d1.dependents, c)
	d2.dependents = append(d2.dependents, c)
	c.value = c.compute()
	r.cells = append(r.cells, c)
	return c
}

