from collections import deque


class StackUnderflowError(Exception):
    pass


def _is_number(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def _pop_two(stack):
    if len(stack) < 2:
        raise StackUnderflowError("Insufficient number of items in stack")
    b = stack.pop()
    a = stack.pop()
    return a, b


def _execute(tokens, stack, words):
    queue = deque(tokens)
    while queue:
        tok = queue.popleft()
        if tok in words:
            queue.extendleft(reversed(words[tok]))
            continue
        if _is_number(tok):
            stack.append(int(tok))
            continue
        if tok in ("+", "-", "*", "/"):
            a, b = _pop_two(stack)
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:
                if b == 0:
                    raise ZeroDivisionError("divide by zero")
                stack.append(int(a / b))
        elif tok == "dup":
            if len(stack) < 1:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.append(stack[-1])
        elif tok == "drop":
            if len(stack) < 1:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.pop()
        elif tok == "swap":
            a, b = _pop_two(stack)
            stack.append(b)
            stack.append(a)
        elif tok == "over":
            a, b = _pop_two(stack)
            stack.append(a)
            stack.append(b)
            stack.append(a)
        else:
            raise ValueError("undefined operation")


def evaluate(input_data):
    stack = []
    words = {}
    for line in input_data:
        tokens = line.lower().split()
        buf = []
        i = 0
        while i < len(tokens):
            if tokens[i] == ":":
                _execute(buf, stack, words)
                buf = []
                end = None
                for j in range(i + 1, len(tokens)):
                    if tokens[j] == ";":
                        end = j
                        break
                if end is None:
                    raise ValueError("unterminated definition")
                if end < i + 2:
                    raise ValueError("illegal operation")
                name = tokens[i + 1]
                if _is_number(name):
                    raise ValueError("illegal operation")
                body = []
                for t in tokens[i + 2:end]:
                    body.extend(words.get(t, [t]))
                words[name] = body
                i = end + 1
            else:
                buf.append(tokens[i])
                i += 1
        _execute(buf, stack, words)
    return stack

