package react

type reactor struct {
	computes []*cell
}

type cell struct {
	value     int
	compute   func() int
	callbacks map[int]func(int)
	nextID    int
	reactor   *reactor
}

type canceler struct {
	c  *cell
	id int
}

type changed struct {
	c   *cell
	old int
}

func (c *canceler) Cancel() {
	delete(c.c.callbacks, c.id)
}

func (c *cell) Value() int {
	return c.value
}

func (c *cell) SetValue(value int) {
	if value == c.value {
		return
	}
	c.value = value

	var changes []changed
	for _, cc := range c.reactor.computes {
		old := cc.value
		cc.value = cc.compute()
		if cc.value != old {
			changes = append(changes, changed{cc, old})
		}
	}

	for _, ch := range changes {
		if ch.c.value == ch.old {
			continue
		}
		for _, cb := range ch.c.callbacks {
			cb(ch.c.value)
		}
	}
}

func (c *cell) AddCallback(callback func(int)) Canceler {
	id := c.nextID
	c.nextID++
	c.callbacks[id] = callback
	return &canceler{c: c, id: id}
}

func New() Reactor {
	return &reactor{}
}

func (r *reactor) CreateInput(initial int) InputCell {
	return &cell{
		value:     initial,
		callbacks: make(map[int]func(int)),
		reactor:   r,
	}
}

func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	c := &cell{
		callbacks: make(map[int]func(int)),
		reactor:   r,
	}
	c.compute = func() int { return compute(dep.Value()) }
	c.value = c.compute()
	r.computes = append(r.computes, c)
	return c
}

func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	c := &cell{
		callbacks: make(map[int]func(int)),
		reactor:   r,
	}
	c.compute = func() int { return compute(dep1.Value(), dep2.Value()) }
	c.value = c.compute()
	r.computes = append(r.computes, c)
	return c
}

