import re


class StackUnderflowError(Exception):
    pass


_NUMBER = re.compile(r"-?\d+")


def _binary(stack, op):
    if len(stack) < 2:
        raise StackUnderflowError("Insufficient number of items in stack")
    b = stack.pop()
    a = stack.pop()
    stack.append(op(a, b))


def _div(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _need(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")


def _dup(stack):
    _need(stack, 1)
    stack.append(stack[-1])


def _drop(stack):
    _need(stack, 1)
    stack.pop()


def _swap(stack):
    _need(stack, 2)
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _over(stack):
    _need(stack, 2)
    stack.append(stack[-2])


BUILTINS = {
    "+": lambda s: _binary(s, lambda a, b: a + b),
    "-": lambda s: _binary(s, lambda a, b: a - b),
    "*": lambda s: _binary(s, lambda a, b: a * b),
    "/": lambda s: _binary(s, _div),
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def evaluate(input_data):
    stack = []
    user_words = {}
    tokens = " ".join(input_data).lower().split()

    i = 0
    while i < len(tokens):
        tok = tokens[i]
        i += 1
        if tok == ":":
            if i >= len(tokens):
                raise ValueError("illegal operation")
            name = tokens[i]
            i += 1
            if _NUMBER.fullmatch(name):
                raise ValueError("illegal operation")
            body = []
            while i < len(tokens) and tokens[i] != ";":
                word = tokens[i]
                i += 1
                if word in user_words:
                    body.extend(user_words[word])
                else:
                    body.append(word)
            if i >= len(tokens):
                raise ValueError("illegal operation")
            i += 1  # skip ';'
            user_words[name] = body
            continue

        if tok in user_words:
            _run(stack, user_words[tok])
        else:
            _run(stack, [tok])

    return stack


def _run(stack, tokens):
    for tok in tokens:
        if _NUMBER.fullmatch(tok):
            stack.append(int(tok))
        elif tok in BUILTINS:
            BUILTINS[tok](stack)
        else:
            raise ValueError("undefined operation")

