package bowling

import "errors"

type Game struct {
	rolls    []int
	frame    int
	first    bool
	standing int
	tenth    []int
	done     bool
}

func NewGame() *Game {
	return &Game{first: true, standing: 10}
}

func (g *Game) Roll(pins int) error {
	if g.done {
		return errors.New("game over")
	}
	if pins < 0 {
		return errors.New("negative roll")
	}
	if pins > g.standing {
		return errors.New("pin count exceeds pins on the lane")
	}
	g.rolls = append(g.rolls, pins)
	if g.frame < 9 {
		if g.first && pins == 10 {
			g.frame++
			g.standing = 10
		} else if g.first {
			g.first = false
			g.standing -= pins
		} else {
			g.frame++
			g.first = true
			g.standing = 10
		}
		return nil
	}
	g.tenth = append(g.tenth, pins)
	g.standing -= pins
	if g.standing == 0 {
		g.standing = 10
	}
	n := len(g.tenth)
	if n == 2 && g.tenth[0]+g.tenth[1] < 10 {
		g.done = true
	} else if n == 3 {
		g.done = true
	}
	return nil
}

func (g *Game) Score() (int, error) {
	if !g.done {
		return 0, errors.New("game not finished")
	}
	r := g.rolls
	score, i := 0, 0
	for f := 0; f < 10; f++ {
		if r[i] == 10 {
			score += 10 + r[i+1] + r[i+2]
			i++
		} else if r[i]+r[i+1] == 10 {
			score += 10 + r[i+2]
			i += 2
		} else {
			score += r[i] + r[i+1]
			i += 2
		}
	}
	return score, nil
}

