import java.awt.Point;
import java.util.*;

class GoCounting {

    private final String[] rows;
    private final int width;
    private final int height;

    GoCounting(String board) {
        rows = board.split("\n");
        height = rows.length;
        width = height == 0 ? 0 : rows[0].length();
    }

    private char at(int x, int y) {
        return x < rows[y].length() ? rows[y].charAt(x) : ' ';
    }

    private void check(int x, int y) {
        if (x < 0 || y < 0 || x >= width || y >= height) {
            throw new IllegalArgumentException("Invalid coordinate");
        }
    }

    private Player fill(int x, int y, Set<Point> region) {
        if (at(x, y) != ' ') return Player.NONE;
        boolean black = false, white = false;
        Deque<Point> stack = new ArrayDeque<>();
        Point start = new Point(x, y);
        stack.push(start);
        region.add(start);
        int[][] d = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!stack.isEmpty()) {
            Point p = stack.pop();
            for (int[] dd : d) {
                int nx = p.x + dd[0], ny = p.y + dd[1];
                if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
                char c = at(nx, ny);
                if (c == 'B') black = true;
                else if (c == 'W') white = true;
                else {
                    Point q = new Point(nx, ny);
                    if (region.add(q)) stack.push(q);
                }
            }
        }
        if (black && !white) return Player.BLACK;
        if (white && !black) return Player.WHITE;
        return Player.NONE;
    }

    Player getTerritoryOwner(int x, int y) {
        check(x, y);
        return fill(x, y, new HashSet<>());
    }

    Set<Point> getTerritory(int x, int y) {
        check(x, y);
        Set<Point> region = new HashSet<>();
        fill(x, y, region);
        return region;
    }

    Map<Player, Set<Point>> getTerritories() {
        Map<Player, Set<Point>> result = new HashMap<>();
        result.put(Player.BLACK, new HashSet<>());
        result.put(Player.WHITE, new HashSet<>());
        result.put(Player.NONE, new HashSet<>());
        Set<Point> seen = new HashSet<>();
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                if (at(x, y) != ' ' || seen.contains(new Point(x, y))) continue;
                Set<Point> region = new HashSet<>();
                Player owner = fill(x, y, region);
                seen.addAll(region);
                result.get(owner).addAll(region);
            }
        }
        return result;
    }

}

