import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.SortedMap;
import java.util.TreeMap;

class PalindromeCalculator {

    SortedMap<Long, List<List<Integer>>> getPalindromeProductsWithFactors(int minFactor, int maxFactor) {
        if (minFactor > maxFactor) {
            throw new IllegalArgumentException("invalid input: min must be <= max");
        }
        SortedMap<Long, List<List<Integer>>> result = new TreeMap<>();

        long best = -1;
        List<List<Integer>> bestF = new ArrayList<>();
        for (long i = minFactor; i <= maxFactor; i++) {
            if (best >= 0 && i * i > best) break;
            for (long j = i; j <= maxFactor; j++) {
                long p = i * j;
                if (best >= 0 && p > best) break;
                if (isPal(p)) {
                    if (best < 0 || p < best) {
                        best = p;
                        bestF = new ArrayList<>();
                    }
                    bestF.add(Arrays.asList((int) i, (int) j));
                    break;
                }
            }
        }
        if (best < 0) return result;
        result.put(best, bestF);

        best = -1;
        bestF = new ArrayList<>();
        for (long i = maxFactor; i >= minFactor; i--) {
            if (best >= 0 && i * maxFactor < best) break;
            for (long j = maxFactor; j >= i; j--) {
                long p = i * j;
                if (best >= 0 && p < best) break;
                if (isPal(p)) {
                    if (p > best) {
                        best = p;
                        bestF = new ArrayList<>();
                    }
                    bestF.add(Arrays.asList((int) i, (int) j));
                    break;
                }
            }
        }
        if (result.containsKey(best)) {
            List<List<Integer>> merged = new ArrayList<>(result.get(best));
            for (List<Integer> f : bestF) if (!merged.contains(f)) merged.add(f);
            result.put(best, merged);
        } else {
            result.put(best, bestF);
        }
        return result;
    }

    private static boolean isPal(long n) {
        long r = 0, m = n;
        while (m > 0) {
            r = r * 10 + m % 10;
            m /= 10;
        }
        return r == n;
    }
}

