const isNum = (t) => /^-?\d+$/.test(t);

export class Forth {
  constructor() {
    this._stack = [];
    this.defs = {};
  }

  pop() {
    if (this._stack.length === 0) throw new Error('Stack empty');
    return this._stack.pop();
  }

  expand(tokens) {
    const out = [];
    for (const t of tokens) {
      if (!isNum(t) && this.defs[t]) out.push(...this.defs[t]);
      else out.push(t);
    }
    return out;
  }

  evaluate(input) {
    const tokens = input.toLowerCase().split(/\s+/).filter(Boolean);
    let i = 0;
    while (i < tokens.length) {
      const t = tokens[i];
      if (t === ':') {
        const end = tokens.indexOf(';', i);
        if (end === -1) throw new Error('Invalid definition');
        const name = tokens[i + 1];
        if (name === undefined || isNum(name)) throw new Error('Invalid definition');
        this.defs[name] = this.expand(tokens.slice(i + 2, end));
        i = end + 1;
        continue;
      }
      for (const w of this.expand([t])) this.exec(w);
      i++;
    }
  }

  exec(t) {
    const s = this._stack;
    if (isNum(t)) {
      s.push(parseInt(t, 10));
      return;
    }
    let a, b;
    switch (t) {
      case '+': b = this.pop(); a = this.pop(); s.push(a + b); break;
      case '-': b = this.pop(); a = this.pop(); s.push(a - b); break;
      case '*': b = this.pop(); a = this.pop(); s.push(a * b); break;
      case '/':
        b = this.pop(); a = this.pop();
        if (b === 0) throw new Error('Division by zero');
        s.push(Math.trunc(a / b));
        break;
      case 'dup': a = this.pop(); s.push(a, a); break;
      case 'drop': this.pop(); break;
      case 'swap': b = this.pop(); a = this.pop(); s.push(b, a); break;
      case 'over': b = this.pop(); a = this.pop(); s.push(a, b, a); break;
      default: throw new Error('Unknown command');
    }
  }

  get stack() {
    return [...this._stack];
  }
}

