const COLORS = [
  'black', 'brown', 'red', 'orange', 'yellow',
  'green', 'blue', 'violet', 'grey', 'white',
];

export class ResistorColorTrio {
  constructor(colors) {
    this.colors = colors;
  }

  get label() {
    const d = this.colors.slice(0, 3).map((c) => {
      const i = COLORS.indexOf(c);
      if (i < 0) throw new Error('invalid color');
      return i;
    });
    let value = (d[0] * 10 + d[1]) * 10 ** d[2];
    const units = [
      [1e9, 'gigaohms'],
      [1e6, 'megaohms'],
      [1e3, 'kiloohms'],
    ];
    for (const [n, u] of units) {
      if (value >= n && value % n === 0) {
        return `Resistor value: ${value / n} ${u}`;
      }
    }
    return `Resistor value: ${value} ohms`;
  }
}

