def transpose(text):
    if not text:
        return ""
    rows = text.split("\n")
    padded = [None] * len(rows)
    width = 0
    for i in range(len(rows) - 1, -1, -1):
        width = max(width, len(rows[i]))
        padded[i] = rows[i].ljust(width)
    maxlen = max(len(r) for r in padded)
    out = []
    for c in range(maxlen):
        out.append("".join(r[c] for r in padded if c < len(r)))
    return "\n".join(out)

