fn translate_word(w: &str) -> String {
    let b = w.as_bytes();
    let is_vowel = |c: u8| b"aeiou".contains(&c);
    if b.is_empty() {
        return String::new();
    }
    if is_vowel(b[0]) || w.starts_with("xr") || w.starts_with("yt") {
        return format!("{w}ay");
    }
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if is_vowel(c) || (c == b'y' && i > 0) {
            break;
        }
        if c == b'q' && i + 1 < b.len() && b[i + 1] == b'u' {
            i += 2;
            break;
        }
        i += 1;
    }
    format!("{}{}ay", &w[i..], &w[..i])
}

pub fn translate(input: &str) -> String {
    input
        .split_whitespace()
        .map(translate_word)
        .collect::<Vec<_>>()
        .join(" ")
}

const ONES: [&str; 20] = [
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
    "nineteen",
];
const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
];
const SCALES: [&str; 7] = [
    "", "thousand", "million", "billion", "trillion", "quadrillion", "quintillion",
];

fn below_thousand(n: u64) -> String {
    let mut parts = Vec::new();
    let h = n / 100;
    let r = n % 100;
    if h > 0 {
        parts.push(format!("{} hundred", ONES[h as usize]));
    }
    if r > 0 {
        if r < 20 {
            parts.push(ONES[r as usize].to_string());
        } else if r % 10 == 0 {
            parts.push(TENS[(r / 10) as usize].to_string());
        } else {
            parts.push(format!("{}-{}", TENS[(r / 10) as usize], ONES[(r % 10) as usize]));
        }
    }
    parts.join(" ")
}

pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }
    let mut chunks = Vec::new();
    let mut m = n;
    while m > 0 {
        chunks.push(m % 1000);
        m /= 1000;
    }
    let mut parts = Vec::new();
    for (i, &c) in chunks.iter().enumerate().rev() {
        if c == 0 {
            continue;
        }
        let mut s = below_thousand(c);
        if i > 0 {
            s.push(' ');
            s.push_str(SCALES[i]);
        }
        parts.push(s);
    }
    parts.join(" ")
}

