package bowling

import "errors"

// Game keeps track of the rolls of a bowling game.
type Game struct {
	rolls []int // all rolls so far
	frame int   // current frame index, 0..9 (9 = tenth frame)
	first int   // pending first roll in frame 0..8, -1 if none
	tenth []int // rolls made in the tenth frame
}

// NewGame creates a new bowling game.
func NewGame() *Game {
	return &Game{first: -1}
}

func (g *Game) isOver() bool {
	if g.frame < 9 {
		return false
	}
	n := len(g.tenth)
	switch {
	case n == 3:
		return true
	case n == 2:
		return g.tenth[0] != 10 && g.tenth[0]+g.tenth[1] != 10
	}
	return false
}

// Roll records the number of pins knocked down by a single roll.
func (g *Game) Roll(pins int) error {
	if g.isOver() {
		return errors.New("cannot roll after game is over")
	}
	if pins < 0 {
		return errors.New("negative roll is invalid")
	}
	if pins > 10 {
		return errors.New("pin count exceeds pins on the lane")
	}

	if g.frame < 9 {
		if g.first < 0 {
			if pins == 10 {
				g.frame++
			} else {
				g.first = pins
			}
		} else {
			if g.first+pins > 10 {
				return errors.New("pin count exceeds pins on the lane")
			}
			g.first = -1
			g.frame++
		}
	} else {
		n := len(g.tenth)
		if n == 1 {
			t0 := g.tenth[0]
			if t0 != 10 && t0+pins > 10 {
				return errors.New("pin count exceeds pins on the lane")
			}
		}
		if n == 2 {
			t0, t1 := g.tenth[0], g.tenth[1]
			if t0 == 10 && t1 != 10 && t1+pins > 10 {
				return errors.New("pin count exceeds pins on the lane")
			}
		}
		g.tenth = append(g.tenth, pins)
	}
	g.rolls = append(g.rolls, pins)
	return nil
}

// Score returns the total score of the game. It is an error to call
// Score before the game is complete.
func (g *Game) Score() (int, error) {
	if !g.isOver() {
		return 0, errors.New("score cannot be taken until the end of the game")
	}
	score := 0
	i := 0
	for f := 0; f < 10; f++ {
		if f == 9 {
			for _, r := range g.rolls[i:] {
				score += r
			}
			break
		}
		if g.rolls[i] == 10 {
			score += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		} else if g.rolls[i]+g.rolls[i+1] == 10 {
			score += 10 + g.rolls[i+2]
			i += 2
		} else {
			score += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return score, nil
}

