import java.awt.Point;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class GoCounting {

    private final char[][] grid;
    private final int width;
    private final int height;

    GoCounting(String board) {
        String[] lines = board.split("\n", -1);
        height = lines.length;
        int w = 0;
        for (String line : lines) {
            w = Math.max(w, line.length());
        }
        width = w;
        grid = new char[height][width];
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                char c = x < lines[y].length() ? lines[y].charAt(x) : ' ';
                grid[y][x] = (c == 'B' || c == 'W') ? c : ' ';
            }
        }
    }

    Player getTerritoryOwner(int x, int y) {
        checkCoordinate(x, y);
        Set<Character> borders = new HashSet<>();
        floodFill(x, y, borders, new HashSet<>());
        return owner(borders);
    }

    Set<Point> getTerritory(int x, int y) {
        checkCoordinate(x, y);
        Set<Character> borders = new HashSet<>();
        return floodFill(x, y, borders, new HashSet<>());
    }

    Map<Player, Set<Point>> getTerritories() {
        Map<Player, Set<Point>> result = new HashMap<>();
        result.put(Player.BLACK, new HashSet<>());
        result.put(Player.WHITE, new HashSet<>());
        result.put(Player.NONE, new HashSet<>());

        Set<Point> seen = new HashSet<>();
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                if (isStone(x, y) || seen.contains(new Point(x, y))) {
                    continue;
                }
                Set<Character> borders = new HashSet<>();
                Set<Point> region = floodFill(x, y, borders, seen);
                result.get(owner(borders)).addAll(region);
            }
        }
        return result;
    }

    private void checkCoordinate(int x, int y) {
        if (x < 0 || y < 0 || x >= width || y >= height) {
            throw new IllegalArgumentException("Invalid coordinate");
        }
    }

    private boolean isStone(int x, int y) {
        return grid[y][x] == 'B' || grid[y][x] == 'W';
    }

    /**
     * Flood fills the empty region containing (x, y), collecting the colours
     * of bordering stones. Visited points are added to {@code visited}.
     */
    private Set<Point> floodFill(int x, int y, Set<Character> borders, Set<Point> visited) {
        Set<Point> region = new HashSet<>();
        if (isStone(x, y)) {
            return region;
        }
        Deque<Point> queue = new ArrayDeque<>();
        Point start = new Point(x, y);
        queue.add(start);
        visited.add(start);
        region.add(start);
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            for (int[] d : dirs) {
                int nx = p.x + d[0];
                int ny = p.y + d[1];
                if (nx < 0 || ny < 0 || nx >= width || ny >= height) {
                    continue;
                }
                if (isStone(nx, ny)) {
                    borders.add(grid[ny][nx]);
                    continue;
                }
                Point np = new Point(nx, ny);
                if (!visited.contains(np)) {
                    visited.add(np);
                    region.add(np);
                    queue.add(np);
                }
            }
        }
        return region;
    }

    private Player owner(Set<Character> borders) {
        if (borders.size() == 1) {
            return borders.contains('B') ? Player.BLACK : Player.WHITE;
        }
        return Player.NONE;
    }
}

