//
// Forth evaluator
//

const NUMBER = /^-?\d+$/;

function binaryOp(stack, fn) {
  if (stack.length < 2) {
    throw new Error('Stack empty');
  }
  const b = stack.pop();
  const a = stack.pop();
  stack.push(fn(a, b));
}

const BUILTINS = {
  '+': (s) => binaryOp(s, (a, b) => a + b),
  '-': (s) => binaryOp(s, (a, b) => a - b),
  '*': (s) => binaryOp(s, (a, b) => a * b),
  '/': (s) => {
    if (s.length < 2) {
      throw new Error('Stack empty');
    }
    const b = s[s.length - 1];
    if (b === 0) {
      throw new Error('Division by zero');
    }
    binaryOp(s, (a, b2) => Math.trunc(a / b2));
  },
  dup: (s) => {
    if (s.length < 1) throw new Error('Stack empty');
    s.push(s[s.length - 1]);
  },
  drop: (s) => {
    if (s.length < 1) throw new Error('Stack empty');
    s.pop();
  },
  swap: (s) => {
    if (s.length < 2) throw new Error('Stack empty');
    const n = s.length;
    [s[n - 2], s[n - 1]] = [s[n - 1], s[n - 2]];
  },
  over: (s) => {
    if (s.length < 2) throw new Error('Stack empty');
    s.push(s[s.length - 2]);
  },
};

export class Forth {
  constructor() {
    this._stack = [];
    this._words = new Map();
  }

  evaluate(input) {
    const tokens = input.trim().split(/\s+/).filter((t) => t.length > 0);
    let i = 0;
    while (i < tokens.length) {
      const tok = tokens[i];
      if (tok === ':') {
        const end = tokens.indexOf(';', i + 1);
        if (end === -1) {
          throw new Error('Invalid definition');
        }
        const name = tokens[i + 1];
        if (name === undefined || end === i + 1 || NUMBER.test(name)) {
          throw new Error('Invalid definition');
        }
        const body = this._compile(tokens.slice(i + 2, end));
        this._words.set(name.toLowerCase(), body);
        i = end + 1;
      } else {
        const ops = this._compile([tok]);
        this._run(ops);
        i++;
      }
    }
  }

  get stack() {
    return this._stack;
  }

  _compile(tokens) {
    const ops = [];
    for (const raw of tokens) {
      const t = raw.toLowerCase();
      if (NUMBER.test(t)) {
        ops.push({ kind: 'push', value: parseInt(t, 10) });
      } else if (this._words.has(t)) {
        ops.push(...this._words.get(t));
      } else if (Object.prototype.hasOwnProperty.call(BUILTINS, t)) {
        ops.push({ kind: 'prim', fn: BUILTINS[t] });
      } else {
        ops.push({ kind: 'unknown', name: t });
      }
    }
    return ops;
  }

  _run(ops) {
    for (const op of ops) {
      if (op.kind === 'push') {
        this._stack.push(op.value);
      } else if (op.kind === 'prim') {
        op.fn(this._stack);
      } else {
        throw new Error('Unknown command');
      }
    }
  }
}

