//
// This is only a SKELETON file for the 'Resistor Color Trio' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const COLORS = [
  'black',
  'brown',
  'red',
  'orange',
  'yellow',
  'green',
  'blue',
  'violet',
  'grey',
  'white',
];

function colorValue(color) {
  const index = COLORS.indexOf(color);
  if (index === -1) {
    throw new Error('invalid color');
  }
  return index;
}

export class ResistorColorTrio {
  constructor(colors) {
    const [first, second, third] = colors;
    const main = colorValue(first) * 10 + colorValue(second);
    const zeros = colorValue(third);
    this.total = main * 10 ** zeros;
  }

  get label() {
    const units = [
      { factor: 1e9, name: 'gigaohms' },
      { factor: 1e6, name: 'megaohms' },
      { factor: 1e3, name: 'kiloohms' },
    ];
    let value = this.total;
    let unit = 'ohms';
    for (const u of units) {
      if (this.total >= u.factor) {
        value = this.total / u.factor;
        unit = u.name;
        break;
      }
    }
    return `Resistor value: ${value} ${unit}`;
  }
}

