def transpose(text):
    lines = text.split("\n")
    width = max((len(line) for line in lines), default=0)
    rows = []
    for i in range(width):
        # Last line that actually has a character in column i.
        last = max(j for j, line in enumerate(lines) if len(line) > i)
        row = "".join(
            lines[j][i] if i < len(lines[j]) else " "
            for j in range(last + 1)
        )
        rows.append(row)
    return "\n".join(rows)

