fn is_vowel(c: char) -> bool {
    matches!(c, 'a' | 'e' | 'i' | 'o' | 'u')
}

fn translate_word(word: &str) -> String {
    let chars: Vec<char> = word.chars().collect();
    let len = chars.len();

    if len == 0 {
        return String::new();
    }

    let starts_with = |p: &str| word.starts_with(p);
    if is_vowel(chars[0]) || starts_with("xr") || starts_with("yt") {
        return format!("{word}ay");
    }

    let mut i = 0;
    while i < len && !is_vowel(chars[i]) {
        if chars[i] == 'q' && i + 1 < len && chars[i + 1] == 'u' {
            i += 2;
            break;
        }
        if chars[i] == 'y' && i > 0 {
            break;
        }
        i += 1;
    }

    let prefix: String = chars[..i].iter().collect();
    let rest: String = chars[i..].iter().collect();
    format!("{rest}{prefix}ay")
}

pub fn translate(input: &str) -> String {
    input
        .split_whitespace()
        .map(translate_word)
        .collect::<Vec<_>>()
        .join(" ")
}

const ONES: [&str; 20] = [
    "zero",
    "one",
    "two",
    "three",
    "four",
    "five",
    "six",
    "seven",
    "eight",
    "nine",
    "ten",
    "eleven",
    "twelve",
    "thirteen",
    "fourteen",
    "fifteen",
    "sixteen",
    "seventeen",
    "eighteen",
    "nineteen",
];

const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
];

const SCALES: [&str; 7] = [
    "",
    "thousand",
    "million",
    "billion",
    "trillion",
    "quadrillion",
    "quintillion",
];

fn below_100(n: usize) -> String {
    if n < 20 {
        ONES[n].to_string()
    } else {
        let mut s = TENS[n / 10].to_string();
        if n % 10 != 0 {
            s.push('-');
            s.push_str(ONES[n % 10]);
        }
        s
    }
}

fn below_1000(n: usize) -> String {
    let hundreds = n / 100;
    let rem = n % 100;
    let mut parts: Vec<String> = Vec::new();
    if hundreds > 0 {
        parts.push(format!("{} hundred", ONES[hundreds]));
    }
    if rem > 0 {
        parts.push(below_100(rem));
    }
    parts.join(" ")
}

pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }
    let mut chunks: Vec<u64> = Vec::new();
    let mut m = n;
    while m > 0 {
        chunks.push(m % 1000);
        m /= 1000;
    }
    let mut words: Vec<String> = Vec::new();
    for (i, &c) in chunks.iter().enumerate().rev() {
        if c == 0 {
            continue;
        }
        let mut s = below_1000(c as usize);
        if i > 0 {
            s.push(' ');
            s.push_str(SCALES[i]);
        }
        words.push(s);
    }
    words.join(" ")
}

