package bowling

import "errors"

// Game keeps track of the rolls of a bowling game.
type Game struct {
	rolls   []int // every roll so far
	frame   int   // index of current frame for frames 1-9 (0-based)
	pending int   // first roll of current frame (1-9), or -1 if none
	tenth   []int // rolls in the tenth frame (including fill balls)
	done    bool  // true once the game is complete
}

// NewGame creates a new bowling game.
func NewGame() *Game {
	return &Game{pending: -1}
}

// Roll records the number of pins knocked down by one ball.
func (g *Game) Roll(pins int) error {
	if pins < 0 || pins > 10 {
		return errors.New("pins must be between 0 and 10")
	}
	if g.done {
		return errors.New("cannot roll after game is over")
	}

	if g.frame < 9 {
		if g.pending < 0 {
			if pins == 10 {
				g.frame++
			} else {
				g.pending = pins
			}
		} else {
			if g.pending+pins > 10 {
				return errors.New("pin count exceeds pins on the lane")
			}
			g.pending = -1
			g.frame++
		}
		g.rolls = append(g.rolls, pins)
		return nil
	}

	// Tenth frame.
	k := len(g.tenth)
	if k == 1 && g.tenth[0] < 10 && g.tenth[0]+pins > 10 {
		return errors.New("pin count exceeds pins on the lane")
	}
	if k == 2 && g.tenth[0] == 10 && g.tenth[1] < 10 && g.tenth[1]+pins > 10 {
		return errors.New("pin count exceeds pins on the lane")
	}
	g.tenth = append(g.tenth, pins)
	g.rolls = append(g.rolls, pins)

	n := len(g.tenth)
	if n == 3 || (n == 2 && g.tenth[0]+g.tenth[1] < 10) {
		g.done = true
	}
	return nil
}

// Score returns the total score of the game, or an error if the game is not complete.
func (g *Game) Score() (int, error) {
	if !g.done {
		return 0, errors.New("score cannot be taken until the end of the game")
	}
	total := 0
	i := 0
	for f := 0; f < 9; f++ {
		if g.rolls[i] == 10 {
			total += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		} else if g.rolls[i]+g.rolls[i+1] == 10 {
			total += 10 + g.rolls[i+2]
			i += 2
		} else {
			total += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	for _, p := range g.rolls[i:] {
		total += p
	}
	return total, nil
}

