        this.rows = board.split("\n", -1);
    }

    Player getTerritoryOwner(int x, int y) {
        checkCoordinate(x, y);
        if (isStone(rows[y].charAt(x))) {
            return Player.NONE;
        }
        Region region = fill(x, y);
        return ownerOf(region);
    }

    Set<Point> getTerritory(int x, int y) {
        checkCoordinate(x, y);
        if (isStone(rows[y].charAt(x))) {
            return new HashSet<>();
        }
        return fill(x, y).cells;
    }

    Map<Player, Set<Point>> getTerritories() {
        Map<Player, Set<Point>> result = new HashMap<>();
        result.put(Player.BLACK, new HashSet<>());
        result.put(Player.WHITE, new HashSet<>());
        result.put(Player.NONE, new HashSet<>());

        Set<Point> visited = new HashSet<>();
        for (int y = 0; y < rows.length; y++) {
            for (int x = 0; x < rows[y].length(); x++) {
                if (isStone(rows[y].charAt(x))) {
                    continue;
                }
                Point p = new Point(x, y);
                if (visited.contains(p)) {
                    continue;
                }
                Region region = fill(x, y);
                visited.addAll(region.cells);
                result.get(ownerOf(region)).addAll(region.cells);
            }
        }
        return result;
    }

    private static final class Region {
        final Set<Point> cells = new HashSet<>();
        final Set<Player> borders = new HashSet<>();
    }

    private Player ownerOf(Region region) {
        if (region.borders.size() != 1) {
            return Player.NONE;
        }
        return region.borders.iterator().next();
    }

    private Region fill(int startX, int startY) {
        Region region = new Region();
        Deque<Point> stack = new ArrayDeque<>();
        Point start = new Point(startX, startY);
        region.cells.add(start);
        stack.push(start);

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!stack.isEmpty()) {
            Point p = stack.pop();
            for (int[] d : dirs) {
                int nx = p.x + d[0];
                int ny = p.y + d[1];
                if (!inBounds(nx, ny)) {
                    continue;
                }
                char c = rows[ny].charAt(nx);
                if (isStone(c)) {
                    region.borders.add(c == 'B' ? Player.BLACK : Player.WHITE);
                } else {
                    Point np = new Point(nx, ny);
                    if (region.cells.add(np)) {
                        stack.push(np);
                    }
                }
            }
        }
        return region;
    }

    private boolean inBounds(int x, int y) {
        return y >= 0 && y < rows.length && x >= 0 && x < rows[y].length();
    }

    private void checkCoordinate(int x, int y) {
        if (!inBounds(x, y)) {
            throw new IllegalArgumentException("Invalid coordinate");
        }
    }

    private static boolean isStone(char c) {
        return c == 'B' || c == 'W';
    }

}

