import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.SortedMap;
import java.util.TreeMap;

class PalindromeCalculator {

    SortedMap<Long, List<List<Integer>>> getPalindromeProductsWithFactors(int minFactor, int maxFactor) {
        if (minFactor > maxFactor) {
            throw new IllegalArgumentException("invalid input: min must be <= max");
        }

        TreeMap<Long, List<List<Integer>>> result = new TreeMap<>();
        boolean has = false;
        long minK = 0;
        long maxK = 0;
        List<List<Integer>> minL = null;
        List<List<Integer>> maxL = null;

        for (int i = minFactor; i <= maxFactor; i++) {
            for (int j = i; j <= maxFactor; j++) {
                long p = (long) i * j;
                if (!isPalindrome(p)) {
                    continue;
                }
                List<Integer> pair = Arrays.asList(i, j);
                if (!has) {
                    has = true;
                    minK = p;
                    maxK = p;
                    minL = new ArrayList<>();
                    maxL = new ArrayList<>();
                    minL.add(pair);
                    maxL.add(pair);
                } else {
                    if (p < minK) {
                        minK = p;
                        minL = new ArrayList<>();
                    }
                    if (p == minK) {
                        minL.add(pair);
                    }
                    if (p > maxK) {
                        maxK = p;
                        maxL = new ArrayList<>();
                    }
                    if (p == maxK) {
                        maxL.add(pair);
                    }
                }
            }
        }

        if (has) {
            result.put(minK, minL);
            if (maxK != minK) {
                result.put(maxK, maxL);
            }
        }
        return result;
    }

    private static boolean isPalindrome(long n) {
        long reversed = 0;
        long t = n;
        while (t > 0) {
            reversed = reversed * 10 + t % 10;
            t /= 10;
        }
        return reversed == n;
    }

}

