//
// Forth evaluator: a small subset of Forth supporting arithmetic,
// stack manipulation, and user-defined words.
//

const NUMBER = /^-?\d+$/;

export class Forth {
  constructor() {
    this._stack = [];
    // Map of user-defined word name -> flat array of primitive tokens
    this._words = new Map();
    this._builtins = {
      '+': (s) => this._binary(s, (a, b) => a + b),
      '-': (s) => this._binary(s, (a, b) => a - b),
      '*': (s) => this._binary(s, (a, b) => a * b),
      '/': (s) => this._binary(s, (a, b) => {
        if (b === 0) throw Error('Division by zero');
        return Math.trunc(a / b);
      }),
      dup: (s) => {
        this._need(s, 1);
        s.push(s[s.length - 1]);
      },
      drop: (s) => {
        this._need(s, 1);
        s.pop();
      },
      swap: (s) => {
        this._need(s, 2);
        const b = s.pop();
        const a = s.pop();
        s.push(b, a);
      },
      over: (s) => {
        this._need(s, 2);
        s.push(s[s.length - 2]);
      },
    };
  }

  _need(s, n) {
    if (s.length < n) throw Error('Stack empty');
  }

  _binary(s, op) {
    this._need(s, 2);
    const b = s.pop();
    const a = s.pop();
    s.push(op(a, b));
  }

  // Execute a primitive token (number or built-in), bypassing user words.
  _runPrimitive(tok) {
    if (NUMBER.test(tok)) {
      this._stack.push(parseInt(tok, 10));
      return;
    }
    if (Object.prototype.hasOwnProperty.call(this._builtins, tok)) {
      this._builtins[tok](this._stack);
      return;
    }
    throw Error('Unknown command');
  }

  _isPrimitive(tok) {
    return NUMBER.test(tok) || Object.prototype.hasOwnProperty.call(this._builtins, tok);
  }

  _define(name, body) {
    const expansion = [];
    for (const tok of body) {
      if (this._words.has(tok)) {
        expansion.push(...this._words.get(tok));
      } else if (this._isPrimitive(tok)) {
        expansion.push(tok);
      } else {
        throw Error('Unknown command');
      }
    }
    this._words.set(name, expansion);
  }

  evaluate(input) {
    const tokens = input.toLowerCase().split(/\s+/).filter((t) => t.length > 0);
    let i = 0;
    while (i < tokens.length) {
      const tok = tokens[i++];
      if (tok === ':') {
        const name = tokens[i++];
        if (name === undefined || name === ';' || NUMBER.test(name)) {
          throw Error('Invalid definition');
        }
        const body = [];
        let closed = false;
        while (i < tokens.length) {
          const t = tokens[i++];
          if (t === ';') {
            closed = true;
            break;
          }
          body.push(t);
        }
        if (!closed) throw Error('Invalid definition');
        this._define(name, body);
        continue;
      }
      if (this._words.has(tok)) {
        for (const p of this._words.get(tok)) {
          this._runPrimitive(p);
        }
      } else {
        this._runPrimitive(tok);
      }
    }
  }

  get stack() {
    return [...this._stack];
  }
}

