//
// Resistor Color Trio
//

const COLORS = [
  'black',
  'brown',
  'red',
  'orange',
  'yellow',
  'green',
  'blue',
  'violet',
  'grey',
  'white',
];

const UNITS = ['ohms', 'kiloohms', 'megaohms', 'gigaohms'];

function colorValue(color) {
  const index = COLORS.indexOf(color);
  if (index === -1) {
    throw new Error(`invalid color: ${color}`);
  }
  return index;
}

export class ResistorColorTrio {
  constructor(colors) {
    this.colors = colors;
  }

  get label() {
    const [first, second, third] = this.colors;
    const a = colorValue(first);
    const b = colorValue(second);
    const c = colorValue(third);

    let value = (10 * a + b) * 10 ** c;
    let unitIndex = 0;

    while (value >= 1000 && value % 1000 === 0 && unitIndex < UNITS.length - 1) {
      value /= 1000;
      unitIndex += 1;
    }

    return `Resistor value: ${value} ${UNITS[unitIndex]}`;
  }
}

