fn is_vowel(c: u8) -> bool {
    matches!(c, b'a' | b'e' | b'i' | b'o' | b'u')
}

fn translate_word(word: &str) -> String {
    let b = word.as_bytes();
    if b.is_empty() {
        return String::new();
    }
    if is_vowel(b[0]) || word.starts_with("xr") || word.starts_with("yt") {
        return format!("{word}ay");
    }

    let mut split = b.len();
    for i in 0..b.len() {
        let c = b[i];
        if c == b'q' && i + 1 < b.len() && b[i + 1] == b'u' {
            split = i + 2;
            break;
        }
        if is_vowel(c) || (c == b'y' && i > 0) {
            split = i;
            break;
        }
    }

    format!("{}{}ay", &word[split..], &word[..split])
}

pub fn translate(input: &str) -> String {
    input
        .split_whitespace()
        .map(translate_word)
        .collect::<Vec<_>>()
        .join(" ")
}

const ONES: [&str; 20] = [
    "zero",
    "one",
    "two",
    "three",
    "four",
    "five",
    "six",
    "seven",
    "eight",
    "nine",
    "ten",
    "eleven",
    "twelve",
    "thirteen",
    "fourteen",
    "fifteen",
    "sixteen",
    "seventeen",
    "eighteen",
    "nineteen",
];

const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
];

const SCALES: [&str; 7] = [
    "",
    "thousand",
    "million",
    "billion",
    "trillion",
    "quadrillion",
    "quintillion",
];

/// Spell out a number in 0..1000 (no scale word).
fn say_under_1000(n: u64) -> String {
    let mut parts: Vec<String> = Vec::new();
    let hundreds = n / 100;
    let rem = n % 100;
    if hundreds > 0 {
        parts.push(format!("{} hundred", ONES[hundreds as usize]));
    }
    if rem > 0 {
        if rem < 20 {
            parts.push(ONES[rem as usize].to_string());
        } else {
            let tens = TENS[(rem / 10) as usize];
            let unit = rem % 10;
            if unit > 0 {
                parts.push(format!("{}-{}", tens, ONES[unit as usize]));
            } else {
                parts.push(tens.to_string());
            }
        }
    }
    parts.join(" ")
}

pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }

    // Split into base-1000 groups, least significant first.
    let mut groups: Vec<u64> = Vec::new();
    let mut m = n;
    while m > 0 {
        groups.push(m % 1000);
        m /= 1000;
    }

    let mut pieces: Vec<String> = Vec::new();
    for (i, &g) in groups.iter().enumerate().rev() {
        if g == 0 {
            continue;
        }
        let mut piece = say_under_1000(g);
        if !SCALES[i].is_empty() {
            piece.push(' ');
            piece.push_str(SCALES[i]);
        }
        pieces.push(piece);
    }
    pieces.join(" ")
}

