package bowling

import "errors"

// Game tracks the state of a bowling game as rolls are recorded.
type Game struct {
	rolls    []int // all rolls recorded so far
	frame    int   // current frame, 1..10
	ball     int   // balls thrown in current frame (frames 1-9 only), 0 or 1
	standing int   // pins still standing in the current frame
	tenth    []int // rolls made in the tenth frame
	done     bool  // true once the game is complete
}

// NewGame returns a new, unstarted bowling game.
func NewGame() *Game {
	return &Game{
		frame:    1,
		ball:     0,
		standing: 10,
	}
}

// Roll records a roll of the given number of pins.
func (g *Game) Roll(pins int) error {
	if g.done {
		return errors.New("cannot roll after game is over")
	}
	if pins < 0 {
		return errors.New("negative roll is invalid")
	}
	if pins > g.standing {
		return errors.New("pin count exceeds pins on the lane")
	}

	g.rolls = append(g.rolls, pins)

	if g.frame < 10 {
		if g.ball == 0 {
			if pins == 10 {
				g.nextFrame()
			} else {
				g.standing -= pins
				g.ball = 1
			}
		} else {
			g.nextFrame()
		}
		return nil
	}

	// Tenth frame.
	g.tenth = append(g.tenth, pins)
	g.standing -= pins
	if g.standing == 0 {
		g.standing = 10
	}
	switch len(g.tenth) {
	case 2:
		if g.tenth[0]+g.tenth[1] < 10 {
			g.done = true
		}
	case 3:
		g.done = true
	}
	return nil
}

// nextFrame advances to the next frame, or into the tenth frame.
func (g *Game) nextFrame() {
	g.frame++
	g.ball = 0
	g.standing = 10
}

// Score returns the total score of a completed game.
func (g *Game) Score() (int, error) {
	if !g.done {
		return 0, errors.New("score cannot be taken until the end of the game")
	}
	total := 0
	i := 0
	for frame := 0; frame < 9; frame++ {
		if g.rolls[i] == 10 {
			total += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		} else if g.rolls[i]+g.rolls[i+1] == 10 {
			total += 10 + g.rolls[i+2]
			i += 2
		} else {
			total += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	// Tenth frame: total pins knocked down, including fill balls.
	for _, p := range g.rolls[i:] {
		total += p
	}
	return total, nil
}

