import java.awt.Point;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class GoCounting {

    private final char[][] grid;
    private final int height;
    private final int width;

    GoCounting(String board) {
        String[] lines = board.split("\n", -1);
        height = lines.length;
        grid = new char[height][];
        int w = 0;
        for (int i = 0; i < height; i++) {
            grid[i] = lines[i].toCharArray();
            w = Math.max(w, grid[i].length);
        }
        width = w;
    }

    private void check(int x, int y) {
        if (y < 0 || y >= height || x < 0 || x >= grid[y].length) {
            throw new IllegalArgumentException("Invalid coordinate");
        }
    }

    private Set<Point> fill(int x, int y, Set<Player> owners) {
        Set<Point> region = new HashSet<>();
        Deque<Point> stack = new ArrayDeque<>();
        Point start = new Point(x, y);
        region.add(start);
        stack.push(start);
        int[][] d = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!stack.isEmpty()) {
            Point p = stack.pop();
            for (int[] v : d) {
                int nx = p.x + v[0];
                int ny = p.y + v[1];
                if (ny < 0 || ny >= height || nx < 0 || nx >= grid[ny].length) {
                    continue;
                }
                char c = grid[ny][nx];
                if (c == 'B') {
                    owners.add(Player.BLACK);
                } else if (c == 'W') {
                    owners.add(Player.WHITE);
                } else {
                    Point q = new Point(nx, ny);
                    if (region.add(q)) {
                        stack.push(q);
                    }
                }
            }
        }
        return region;
    }

    private boolean isStone(int x, int y) {
        char c = grid[y][x];
        return c == 'B' || c == 'W';
    }

    private Player ownerOf(Set<Player> owners) {
        return owners.size() == 1 ? owners.iterator().next() : Player.NONE;
    }

    Player getTerritoryOwner(int x, int y) {
        check(x, y);
        if (isStone(x, y)) {
            return Player.NONE;
        }
        Set<Player> owners = new HashSet<>();
        fill(x, y, owners);
        return ownerOf(owners);
    }

    Set<Point> getTerritory(int x, int y) {
        check(x, y);
        if (isStone(x, y)) {
            return new HashSet<>();
        }
        return fill(x, y, new HashSet<>());
    }

    Map<Player, Set<Point>> getTerritories() {
        Map<Player, Set<Point>> result = new HashMap<>();
        result.put(Player.BLACK, new HashSet<>());
        result.put(Player.WHITE, new HashSet<>());
        result.put(Player.NONE, new HashSet<>());
        Set<Point> visited = new HashSet<>();
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < grid[y].length; x++) {
                if (isStone(x, y) || visited.contains(new Point(x, y))) {
                    continue;
                }
                Set<Player> owners = new HashSet<>();
                Set<Point> region = fill(x, y, owners);
                visited.addAll(region);
                result.get(ownerOf(owners)).addAll(region);
            }
        }
        return result;
    }

}

