//
// Forth evaluator: supports + - * / DUP DROP SWAP OVER and user-defined words.
//

const NUMBER = /^-?\d+$/;
const BUILTINS = new Set(['+', '-', '*', '/', 'dup', 'drop', 'swap', 'over']);

export class Forth {
  constructor() {
    this._stack = [];
    this._defs = new Map();
  }

  evaluate(input) {
    const tokens = String(input).toLowerCase().split(/\s+/).filter((t) => t.length > 0);
    let i = 0;
    while (i < tokens.length) {
      const t = tokens[i];
      if (t === ':') {
        const end = tokens.indexOf(';', i + 1);
        if (end === -1) {
          throw new Error('Invalid definition');
        }
        const name = tokens[i + 1];
        if (name === undefined || end === i + 1 || NUMBER.test(name)) {
          throw new Error('Invalid definition');
        }
        const body = [];
        for (const tok of tokens.slice(i + 2, end)) {
          if (this._defs.has(tok)) {
            body.push(...this._defs.get(tok));
          } else if (NUMBER.test(tok) || BUILTINS.has(tok)) {
            body.push(tok);
          } else {
            throw new Error('Unknown command');
          }
        }
        this._defs.set(name, body);
        i = end + 1;
      } else {
        if (this._defs.has(t)) {
          for (const tok of this._defs.get(t)) {
            this._exec(tok);
          }
        } else {
          this._exec(t);
        }
        i++;
      }
    }
  }

  // Executes a single atomic token: a number or a built-in word.
  _exec(tok) {
    const s = this._stack;
    if (NUMBER.test(tok)) {
      s.push(Number(tok));
      return;
    }
    const need = (n) => {
      if (s.length < n) {
        throw new Error('Stack empty');
      }
    };
    switch (tok) {
      case '+': {
        need(2);
        const b = s.pop();
        const a = s.pop();
        s.push(a + b);
        break;
      }
      case '-': {
        need(2);
        const b = s.pop();
        const a = s.pop();
        s.push(a - b);
        break;
      }
      case '*': {
        need(2);
        const b = s.pop();
        const a = s.pop();
        s.push(a * b);
        break;
      }
      case '/': {
        need(2);
        const b = s.pop();
        const a = s.pop();
        if (b === 0) {
          throw new Error('Division by zero');
        }
        s.push(Math.trunc(a / b));
        break;
      }
      case 'dup': {
        need(1);
        s.push(s[s.length - 1]);
        break;
      }
      case 'drop': {
        need(1);
        s.pop();
        break;
      }
      case 'swap': {
        need(2);
        const b = s.pop();
        const a = s.pop();
        s.push(b, a);
        break;
      }
      case 'over': {
        need(2);
        s.push(s[s.length - 2]);
        break;
      }
      default:
        throw new Error('Unknown command');
    }
  }

  get stack() {
    return [...this._stack];
  }
}

