const COLORS = [
  'black',
  'brown',
  'red',
  'orange',
  'yellow',
  'green',
  'blue',
  'violet',
  'grey',
  'white',
];

const UNITS = ['ohms', 'kiloohms', 'megaohms', 'gigaohms'];

export class ResistorColorTrio {
  constructor(colors) {
    this.colors = colors;
    this.digits = colors.slice(0, 3).map((c) => {
      const i = COLORS.indexOf(c);
      if (i === -1) {
        throw new Error('invalid color');
      }
      return i;
    });
  }

  get label() {
    const [d1, d2, d3] = this.digits;
    let value = (d1 * 10 + d2) * 10 ** d3;
    let unit = 0;
    while (value > 0 && value % 1000 === 0 && unit < UNITS.length - 1) {
      value /= 1000;
      unit += 1;
    }
    return `Resistor value: ${value} ${UNITS[unit]}`;
  }
}

