//
// Word Search exercise implementation.
//

class WordSearch {
  constructor(grid) {
    this.grid = grid;
  }

  find(words) {
    const result = {};
    for (const word of words) {
      result[word] = this.findWord(word);
    }
    return result;
  }

  findWord(word) {
    const grid = this.grid;
    const len = word.length;
    const directions = [];
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr !== 0 || dc !== 0) directions.push([dr, dc]);
      }
    }

    for (let r = 0; r < grid.length; r++) {
      for (let c = 0; c < grid[r].length; c++) {
        if (len === 1) {
          if (grid[r][c] === word) {
            return { start: [r + 1, c + 1], end: [r + 1, c + 1] };
          }
          continue;
        }
        for (const [dr, dc] of directions) {
          if (this.matchAt(word, r, c, dr, dc)) {
            return {
              start: [r + 1, c + 1],
              end: [r + 1 + dr * (len - 1), c + 1 + dc * (len - 1)],
            };
          }
        }
      }
    }
    return undefined;
  }

  matchAt(word, r, c, dr, dc) {
    const grid = this.grid;
    for (let i = 0; i < word.length; i++) {
      const rr = r + dr * i;
      const cc = c + dc * i;
      if (rr < 0 || rr >= grid.length) return false;
      if (cc < 0 || cc >= grid[rr].length) return false;
      if (grid[rr][cc] !== word[i]) return false;
    }
    return true;
  }
}

export default WordSearch;

