def transpose(text):
    rows = text.split("\n")
    padded = []
    m = 0
    for row in reversed(rows):
        m = max(m, len(row))
        padded.append(row.ljust(m))
    padded.reverse()
    out = []
    for j in range(m):
        out.append("".join(r[j] for r in padded if len(r) > j))
    return "\n".join(out)

