fn translate_word(word: &str) -> String {
    let bytes = word.as_bytes();
    let is_vowel = |c: u8| matches!(c, b'a' | b'e' | b'i' | b'o' | b'u');

    if bytes.is_empty() {
        return String::new();
    }

    // Rule 1: vowel start, or "xr" / "yt" prefix.
    if is_vowel(bytes[0])
        || word.starts_with("xr")
        || word.starts_with("yt")
    {
        return format!("{word}ay");
    }

    // Rules 2-4: find the end of the consonant prefix.
    let mut split = bytes.len();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if is_vowel(c) {
            split = i;
            break;
        }
        if c == b'y' && i != 0 {
            split = i;
            break;
        }
        if c == b'q' && i + 1 < bytes.len() && bytes[i + 1] == b'u' {
            split = i + 2;
            break;
        }
        i += 1;
    }

    format!("{}{}ay", &word[split..], &word[..split])
}

pub fn translate(input: &str) -> String {
    input
        .split_whitespace()
        .map(translate_word)
        .collect::<Vec<_>>()
        .join(" ")
}

const ONES: [&str; 20] = [
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
    "nineteen",
];
const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
];
const SCALES: [&str; 7] = [
    "", "thousand", "million", "billion", "trillion", "quadrillion", "quintillion",
];

fn chunk(n: u64) -> String {
    let mut parts: Vec<String> = Vec::new();
    let h = n / 100;
    let r = (n % 100) as usize;
    if h > 0 {
        parts.push(format!("{} hundred", ONES[h as usize]));
    }
    if r > 0 {
        if r < 20 {
            parts.push(ONES[r].to_string());
        } else if r % 10 == 0 {
            parts.push(TENS[r / 10].to_string());
        } else {
            parts.push(format!("{}-{}", TENS[r / 10], ONES[r % 10]));
        }
    }
    parts.join(" ")
}

pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }
    let mut parts: Vec<String> = Vec::new();
    let mut rest = n;
    let mut i = 0;
    while rest > 0 {
        let c = rest % 1000;
        if c > 0 {
            let mut s = chunk(c);
            if !SCALES[i].is_empty() {
                s.push(' ');
                s.push_str(SCALES[i]);
            }
            parts.push(s);
        }
        rest /= 1000;
        i += 1;
    }
    parts.reverse();
    parts.join(" ")
}
